function passages(text) {
  const pieces=text.match(/[^。！？]+[。！？]?/g)||[text];
  const frames=[];
  for(const piece of pieces) {
    if(frames.length && frames.at(-1).length+piece.length<=76)frames[frames.length-1]+=piece;
    else frames.push(piece);
  }
  return frames;
}

function flatten(events,node) {
  return events.flatMap((e,eventIndex)=>e.shots.flatMap((s,shotIndex)=>s.frames.map((entry,frameIndex)=>{
    const frame=typeof entry==='string'?{text:entry}:entry;
    const speaker=frame.speaker??s.speaker??e.speaker??(s.character??e.character?'张謇':'旁白');
    return {
      art:s.art,year:e.year??node.year,place:e.place??node.place,
      character:s.character??e.character??false,
      pose:e.id==='laureate'&&shotIndex===0?'greet':/after-laureate|success-and-country|shareholders|school-foundation|ministerial-desk|many-plans|credit-narrows/.test(e.id)?'read':'adult',
      camera:s.camera??(shotIndex%2?'close':'wide'),
      eventId:e.id,eventTitle:e.title,eventIndex,shotIndex,frameIndex,
      refs:e.refs??node.refs,fact:e.fact??node.fact,
      cast:e.cast??[],speaker,speaking:frame.speaking??(speaker==='张謇'?'zhang':null),...frame
    };
  })));
}

export const INTRO = Object.fromEntries(Object.entries(NODES).map(([id,node])=>[id,flatten(EVENTS[id],node)]));

export function aftermath(nodeId,choiceId) {
  const node=NODES[nodeId],choice=node.choices.find(c=>c.id===choiceId);
  const destination=choice.next.startsWith('end:')?null:NODES[choice.next];
  const base=INTRO[nodeId].at(-1);
  const strongest=Object.entries(choice.effects).sort((a,b)=>Math.abs(b[1])-Math.abs(a[1]))[0];
  const implications={industry:'产业能力还需要原料、管理与市场一起支撑，规模增加并不保证每一年的收益。',education:'教育留下的是人的能力，持续办学仍要安排师资、经费与后来能够承担责任的人。',trust:'信任会影响以后能否动员公共支持；一次决定形成的声望，还需要用持续的行动来维护。',cash:'周转余力意味着面对变化时还能作出选择；长期承诺与现金回收的时间，需要继续分清。'};
  const explanation=implications[strongest?.[0]]||implications.trust;
  const first={...base,text:choice.result+choice.description+explanation,eventId:'choice-'+choiceId,eventTitle:choice.title,speaker:'张謇',speaking:'zhang',character:true,pose:'adult',camera:'close',effects:true,frameIndex:0,shotIndex:0};
  const transition=destination?
    `此后，事情开始沿着这条道路展开。接下来，你将走进${destination.place}，面对新的日常与新的难题。`:
    '这一段的决定已经落下。余下的年月，将让你看清这条道路究竟留下了什么。';
  const horizon=destination?'此前的资源和关系将随你进入这一段经历。新的事件会继续检验这项决定，你仍须在具体困难中寻找可以长期承担的办法。':'功名、经营与公共责任不会拥有同一个评价尺度。终章会回看这条道路的成果与限度，也会留下不能由一个人独自解决的问题。';
  return [first,{...base,art:destination?INTRO[choice.next][0].art:base.art,text:transition+horizon,eventId:'choice-'+choiceId,eventTitle:'此后的年月',speaker:'旁白',speaking:null,cast:[],character:false,pose:'adult',camera:'wide'}];
}

export const EPILOGUES=Object.fromEntries(Object.entries(ENDINGS).map(([id,ending])=>{
  const frames=[];
  const arts=[ending.art,'ledger','classroom','museum','river','school'];
  for(const [index,text] of ending.body.entries())for(const piece of passages(text))frames.push({text:piece,art:arts[frames.length%arts.length],year:1926,place:'江海之间',speaker:'旁白',character:false,camera:index?'close':'wide',eventId:'ending-'+id,eventTitle:ending.title,eventIndex:index,shotIndex:frames.length,frameIndex:0,refs:ending.refs,fact:ending.lesson});
  frames.push({text:ending.lesson,art:ending.art,year:1926,place:'江海之间',speaker:'旁白',character:false,camera:'wide',eventId:'ending-'+id,eventTitle:'留给后来的人',eventIndex:2,shotIndex:frames.length,frameIndex:0,refs:ending.refs,fact:ending.lesson});
  const reflections={
    history:['企业的经营关系已经改变，学校与公共机构仍需找到自己的延续办法。个人离开以后，建设的意义也将由后来的人怎样使用这些基础继续说明。','留下成果，并不免除对政治误判与经营边界的追问；承认局限，也不应把教育、公益和产业积累一并视为无意义。','你的一生把传统士人的责任带进了新式生产与社会组织。它既说明地方能够主动改变，也说明国家制度和市场条件始终参与决定它的边界。'],
    balanced:['一次架空选择没有使以后所有困难消失，也不会因为再次遇到相似事件就变回已经发生的历史。你的道路需要连同曾经的取舍一起理解。'],
    education:['学校的延续不只靠一份捐资，还靠教师、管理者和参与者愿意长期承担。人才走向不同地方以后，教育的影响也会离开发起者的直接控制。'],
    prudent:['较小规模仍需有效经营，现金也不能永远停在账上。谨慎的价值，在于为变化保留余地，并让承诺尽量接近实际能够承担的能力。'],
    public:['公共参与需要经费、知识与持续的程序。多人承担能够减少对个人的依赖，却不会使所有利益自动一致，规则仍要在分歧与低潮中被维护。'],
    constitution:['制度的主张需要实际社会力量来支撑；个人可以留下重要问题，却不能仅凭一份倡议使全国权力关系改变。未完成的部分仍有研究和接续的价值。'],
    court:['职位和声望能够保存某些行动机会，却会受到既有权力安排限制。留在旧秩序中的你，也必须面对新的政治现实不再按原方案展开的后果。'],
    partner:['外部资本带来技术与速度，也把更多决定权交给其他参与者。公共建设若希望继续，需要在明确经营边界之外寻找持续的资源与责任。'],
    collapse:['愿望不能替代现金回收与偿债能力，危机也不能抹去曾经有用的人才与机构。对这条道路的评价，需要把成就、误判与经营责任同时看见。'],
    quiet:['退出之后的安静并不使过去重新开始。已有机构能否接续，要看经费、治理与继任者，而不只看发起者是否一直站在事务的中心。']
  };
  for(const [i,frame] of frames.entries())if(frame.text.length<80)frame.text+=reflections[id][i%reflections[id].length];
  return [id,frames];
}));

export function framesFor(state) {
  return state.ending?EPILOGUES[state.ending]:state.pending?aftermath(state.node,state.pending.choice):INTRO[state.node];
}

export function decisionScene(nodeId) { return {...INTRO[nodeId].at(-1),character:true,pose:'adult',speaker:'张謇',speaking:'zhang'}; }

export const NARRATIVE_COUNTS={
  events:Object.values(EVENTS).reduce((n,events)=>n+events.length,0),
  shots:Object.values(EVENTS).flat().reduce((n,e)=>n+e.shots.length,0),
  frames:Object.values(INTRO).reduce((n,frames)=>n+frames.length,0)
};
